SELECT (SELECT group_concat(a||','||b||','||c||','||printf('%.1f',d),'|') FROM (SELECT a,b,c,d FROM t1 ORDER BY rowid)), (SELECT group_concat(x||','||y||','||z,'|') FROM (SELECT x,y,z FROM t2 ORDER BY rowid)), (SELECT group_concat(type||':'||name||':'||tbl_name,'|') FROM (SELECT type,name,tbl_name FROM sqlite_schema WHERE name IN ('t1','t2','i1','i2','v1','v2','v3') ORDER BY name));